    features: `<p>소프트 군집화로 군집 경계의 불확실성을 확률로 표현할 수 있고, 공분산 행렬을 통해 타원형 등 K-평균보다 다양한 모양의 군집을 표현하며, 생성 모델이라 새 데이터의 확률도 계산 가능한 장점, 군집 개수(K)를 미리 지정해야 하고 초기값에 따라 지역 최적해에 빠질 수 있으며, 고차원에서는 공분산 추정이 불안정해지는 단점.</p>`,
