    overview: `<p>변수가 수십~수천 개인 고차원 데이터를 사람이 눈으로 볼 수 있는 2~3차원으로 압축(임베딩)한 뒤, 그 결과를 산점도로 그립니다. 압축 방법으로는 선형인 PCA, 지역 구조를 보존하는 비선형인 t-SNE·UMAP이 주로 쓰이며, 방법에 따라 강조되는 구조(전역 vs 지역)가 다릅니다.</p>`,
