    features: `<p>모델이 단순하여 연산 비용이 매우 낮은 장점, 데이터 분포가 가정과 다를 경우 성능이 급격히 저하되는 한계와 함께 평균·표준편차가 이상치 자체에 오염되어 탐지에 실패할 수 있는 단점.</p>`,
    applications: `<p>정규성이 성립하는 계측 데이터의 기본 이상치 점검, 표준화 전처리와 결합한 간단한 필터링, 이상 탐지의 베이스라인 기법으로 사용.</p>`,
