    subtitle: '일정 구간의 평균이나 중앙값을 기준선으로 삼아 크게 벗어난 값을 이상으로 판정하는 기본 기법',
    overview: `<p>일정 크기 윈도우 안의 값들의 평균 또는 중앙값을 계산해 평활한 기준선을 만들고, 실제값이 이 기준선에서 표준편차의 몇 배 이상 벗어나면 이상으로 판정하는 기법. 중앙값을 쓰면 이상치 자체가 기준선을 오염시키는 문제를 크게 줄일 수 있어 더 강건함.</p>`,
    formula: `MA_t = (1/w) Σ_{i=t−w+1}^{t} y_i  또는  MM_t = median(y_{t−w+1}, ..., y_t),  |y_t − MA_t| > k·σ 이면 이상`,
    features: `<p>개념과 구현이 매우 단순하고 계산이 가벼우며 중앙값 버전은 이상치에 강건한 장점, 윈도우 크기 설정에 결과가 좌우되고 추세·계절성을 반영하지 못하며 윈도우 경계에서 지연이 발생하는 단점.</p>`,
    applications: `<p>모니터링 대시보드의 기본 이상 알림, 센서값의 스파이크 필터링, 시계열 전처리의 평활과 이상 제거에 사용.</p>`,
