    overview: `<p>Meta가 공개한 Prophet은 시계열을 추세·계절성·휴일 효과의 합으로 분해하는 가법 모델로, 결측과 이상치에 강건하고 파라미터 튜닝 없이도 잘 작동하도록 설계됨. 예측값과 함께 제공되는 불확실성 구간(yhat_lower~yhat_upper)을 벗어난 실제값을 이상으로 판정.</p>`,
