    overview: `<p>Twitter가 공개한 기법으로, 일반 ESD 검정이 시계열의 계절성과 추세 때문에 오탐을 내는 문제를 해결. STL 분해로 계절 성분을 제거하고, 평균·표준편차 대신 중앙값과 MAD를 사용하는 강건 통계를 결합해(hybrid) 남은 잔차에 일반화 ESD 검정을 적용.</p>`,
