    overview: `<p>고차원 데이터에서 무관한 특징이 많으면 거리·밀도가 희석되어 이상 신호가 묻히는 문제를 다루는 접근. 정답 레이블이 없으므로 지도학습식 특징 선택을 쓸 수 없어, 특징별 분산·엔트로피·상관구조나 대리 이상 점수와의 연관성 등 비지도 기준으로 관련 특징을 선별하고 그 부분공간에서만 탐지를 수행.</p>`,
