    features: `<p>무관 특징의 잡음을 제거해 이상 신호 대비를 높이고 계산량도 함께 줄이며 결과 해석이 쉬워지는 장점, 정답 레이블이 없어 선택 기준을 정하기 어렵고 이상치마다 관련 특징이 달라 단일 부분집합으로는 일부를 놓치는 단점.</p>`,
    applications: `<p>변수가 수백~수천 개인 고차원 데이터의 이상 탐지 전처리, 어떤 특징이 이상과 관련되는지 해석이 필요한 분석에 사용.</p>`,
