    category: 'unsup',
    subcategory: 'anomaly',
    title: 'HiCS(High Contrast Subspaces) : 고대비 부분공간 기반 이상치 순위화',
    subtitle: '변수 간 종속성이 강해 대비가 높은 부분공간만 골라 그 안에서 이상 점수를 집계하는 기법',
    overview: `<p>고차원 전체 공간에서는 이상치가 묻히지만 특정 부분공간 조합에서는 뚜렷하게 드러난다는 관찰에서 출발한 기법. 조건부 종속성이 강한(대비가 높은) 부분공간을 통계 검정으로 먼저 찾아내고, 그 부분공간들에서만 LOF 등의 이상 점수를 계산해 평균 집계. 탐지기가 아니라 전처리 성격의 부분공간 탐색 기법.</p>`,
    formula: '각 부분공간의 대비 = 조건부 분포와 주변 분포의 편차(통계 검정) → 고대비 부분공간에서만 LOF 집계',
    features: `<p>이상치가 드러나는 부분공간만 골라 전체 공간에서 묻히는 이상치를 찾아내고 어떤 변수 조합에서 이상한지 해석이 가능한 장점, 부분공간 탐색과 통계 검정 비용이 크고 몬테카를로 샘플링 수 등 파라미터가 필요한 단점.</p>`,
    applications: `<p>변수가 많아 전체 공간 탐지가 실패하는 고차원 데이터의 이상 탐지, 이상 원인이 되는 변수 조합을 규명해야 하는 분석에 사용.</p>`,
    sklearnFunction: 'HiCS (ELKI)',
    sklearnGuideURL: 'https://elki-project.github.io/algorithms/',
    sklearnAPIURL: '',
    sklearnExampleURL: '',
    huggingfaceURL: '',
    spaceURL: '',
    papersWithCodeURL: 'https://ls9-www.cs.tu-dortmund.de/publications/ICDE2012.pdf'
