    features: `<p>레이블 비용 없이 대규모 데이터를 활용할 수 있고 학습된 표현이 다양한 과제로 잘 전이되며 지도학습에 필적하는 성능을 내는 장점, pretext 과제 설계가 성능을 좌우하고 사전학습에 막대한 계산 자원이 필요하며 학습된 표현이 목표 과제와 어긋날 수 있는 단점.</p>`,
