    features: `<p>파라미터가 크게 줄어 고차원에서 안정적이고 역행렬·행렬식이 블록별로 계산되어 매우 효율적이며 그룹 구조가 해석에 직접 쓰이는 장점, 그룹 구분을 사전에 알거나 추정해야 하고 그룹 간 실제 상관이 있으면 심각한 편향이 생기는 단점.</p>`,
    applications: `<p>모듈 구조가 뚜렷한 유전자 발현 데이터, 자산군별로 나뉘는 금융 포트폴리오, 독립적 부시스템으로 구성된 센서 네트워크 분석에 사용.</p>`,
