    overview: `<p>우도가 높을수록 좋지만 파라미터가 많아질수록 과적합된다는 점을 반영해, 로그우도에서 파라미터 수에 비례하는 벌점을 빼 모델을 비교하는 지표. AIC는 예측 오차 최소화 관점, BIC는 참 모델 선택 관점에서 유도되며 BIC의 벌점이 더 강해 더 단순한 모델을 고름. GMM의 성분 개수 결정에 표준적으로 사용.</p>`,
    formula: `AIC = −2·log L + 2k,  BIC = −2·log L + k·log n  (k: 파라미터 수, 낮을수록 좋음)`,
    features: `<p>적합도와 복잡도의 균형을 하나의 수치로 제시하고 서로 다른 모델을 정량 비교할 수 있는 장점, 우도가 정의되는 확률 모델(GMM 등)에만 쓸 수 있어 K-평균·DBSCAN에는 적용 불가하고 표본이 작으면 선택이 불안정한 단점.</p>`,
    applications: `<p>GMM의 최적 성분 개수 결정, 확률 모델 기반 군집화의 모델 선택, 회귀·시계열 모형 차수 선택에 널리 사용.</p>`,
