    overview: `<p>항목집합 하나에서 나올 수 있는 여러 규칙의 신뢰도 중 최솟값을 지표로 삼는 방식. 지지도가 가장 큰 항목을 전제로 했을 때의 신뢰도와 같으며, 이 값이 높으면 어느 방향으로 규칙을 만들어도 신뢰도가 보장됨. 하향 폐쇄성을 만족해 효율적 가지치기가 가능.</p>`,
