    category: 'unsup',
    subcategory: 'evaluation',
    title: 'Chi-Square Test : 카이제곱 검정 (연관규칙)',
    subtitle: '전제와 결론이 독립이라는 가설을 검정해 연관의 통계적 유의성을 판정하는 지표',
    overview: `<p>분할표에서 관측 빈도와 독립 가정 하의 기대 빈도 차이를 카이제곱 통계량으로 계산해, 두 항목의 연관이 우연으로 설명될 수 있는지 검정하는 지표. 지지도·신뢰도가 높아도 통계적으로 유의하지 않을 수 있으므로, 규칙의 유의성 검증에 사용.</p>`,
    formula: `χ² = Σ (관측빈도 − 기대빈도)² / 기대빈도,  자유도 1에서 χ² > 3.84 이면 유의(α=0.05)`,
    features: `<p>통계적 유의성이라는 명확한 판정 기준을 제공하고 양·음의 연관을 모두 감지하는 장점, 표본 크기에 비례해 커져 대규모 데이터에서는 사소한 연관도 유의하게 나오고 기대 빈도가 작으면 부정확하며 연관의 방향과 강도를 알려주지 않는 단점.</p>`,
    applications: '<p>연관규칙의 통계적 유의성 검증, 우연한 규칙 필터링, 범주형 변수 간 독립성 검정에 사용.</p>',
    sklearnFunction: 'chi2_contingency (SciPy)',
