    overview: `<p>연관규칙의 흥미도가 만족해야 할 원칙(독립이면 0, 지지도 증가 시 단조 증가 등)을 공리로 정식화하면서 제안된 지표로, 값 자체는 레버리지와 동일한 형태. 규칙 평가 척도 연구의 출발점이 된 개념적 기여가 크며, 여러 흥미도 측도를 비교하는 기준으로 인용됨.</p>`,
    formula: 'PS(X→Y) = support(X ∪ Y) − support(X)·support(Y)  (레버리지와 동일)',
    features: `<p>흥미도 측도가 갖춰야 할 공리를 명시해 이론적 기준을 제공하고 독립일 때 0이라는 해석이 명확한 장점, 값 자체는 레버리지와 같아 실무적 신규성이 없고 지지도가 낮은 항목에서 값이 작아지는 한계를 그대로 갖는 단점.</p>`,
