    overview: `<p>실제값과 추정값 차이를 제곱해 평균낸 값으로, 차원 축소에서는 원 데이터와 복원 데이터의 차이를 재는 데 쓰임. 제곱하기 때문에 큰 오차에 훨씬 큰 벌점을 주며, 미분이 가능해 대부분의 학습 알고리즘이 직접 최소화하는 목적함수로도 사용.</p>`,
