    subtitle: '압축된 표현에서 원 데이터를 복원했을 때 발생하는 차이를 재는 지표',
    overview: `<p>차원 축소나 오토인코더가 원 데이터를 저차원으로 압축한 뒤 다시 복원했을 때, 원본과 복원본의 차이를 재는 지표. 값이 작을수록 압축 과정에서 정보 손실이 적었다는 뜻이며, 이상 탐지에서는 이 값 자체를 이상 점수로 활용.</p>`,
