    subtitle: '거리 오차를 원래 거리로 나누어 가까운 점들의 왜곡에 더 큰 벌점을 주는 스트레스 지표',
    overview: `<p>MDS의 스트레스를 변형해, 각 거리 오차를 원래 거리로 나누어 정규화한 지표. 원래 가까웠던 점들의 거리 오차가 상대적으로 훨씬 큰 벌점을 받으므로, 전역 구조보다 국소 구조 보존을 강조. Sammon 매핑의 목적함수이기도 함.</p>`,
