    title: 'Scree Plot : 스크리 플롯',
    subtitle: '성분별 고유값을 순서대로 그려 꺾이는 지점으로 차원 수를 정하는 시각적 도구',
    overview: `<p>주성분을 x축에, 각 성분의 고유값이나 설명 분산 비율을 y축에 그린 그래프. 처음에는 급격히 떨어지다가 완만해지는 지점(바위 비탈의 자갈더미를 닮아 scree)을 찾아 그 앞까지를 유의미한 성분으로 채택하는 방식으로, 군집화의 엘보 방법과 같은 원리.</p>`,
    formula: 'x축: 성분 번호 i,  y축: 고유값 λ_i (또는 설명 분산 비율) → 기울기가 완만해지는 지점 선택',
    features: `<p>시각적으로 직관적이고 계산이 즉시 되며 성분별 중요도 분포를 한눈에 보여주는 장점, 꺾이는 지점 판단이 주관적이고 곡선이 매끄러우면 기준을 정하기 어려우며 정량적 규칙이 없는 단점.</p>`,
    applications: `<p>PCA·요인분석의 성분 개수 결정, 차원 축소 결과의 시각적 진단, 데이터의 내재 차원 탐색에 널리 사용.</p>`,
    sklearnFunction: 'PCA.explained_variance_',
