    overview: `<p>DBSCAN이 잡음(-1)으로 분류한 점의 비율로, 이상치 탐지 관점에서는 탐지된 이상치의 비율이자 군집화 관점에서는 파라미터 적절성의 진단 지표. 비율이 지나치게 높으면 eps가 너무 작거나 minPts가 너무 크다는 신호.</p>`,
    formula: 'noise_ratio = |{i : label_i = −1}| / n',
