    subtitle: 'Inception Score에 실제 데이터의 클래스 분포 비교를 더해 모드 붕괴를 감지하는 지표',
    overview: `<p>Inception Score가 실제 데이터를 전혀 참조하지 않아 모드 붕괴를 놓치는 문제를 보완한 지표. 생성 이미지의 클래스 분포와 실제 데이터의 클래스 분포 사이 KL 발산을 벌점으로 추가해, 일부 클래스만 반복 생성하면 점수가 낮아지도록 설계.</p>`,
