    subtitle: '생성 품질과 다양성을 각각 정밀도와 재현율로 분리해 평가하는 생성 모델 지표',
    overview: `<p>FID가 품질과 다양성을 하나의 수치로 뭉뚱그리는 문제를 해결하려고, 두 축을 분리해 평가하는 지표. 생성 샘플이 실제 데이터 매니폴드 안에 들어가는 비율을 정밀도(품질), 실제 데이터가 생성 매니폴드 안에 들어가는 비율을 재현율(다양성)로 정의해, 모드 붕괴와 품질 저하를 구분해 진단.</p>`,
    formula: `Precision = (1/M)Σ_j I(y_j ∈ manifold(X_r)),  Recall = (1/N)Σ_i I(x_i ∈ manifold(X_g))`,
