    overview: `<p>데이터를 k개 부분으로 나눈 뒤 하나씩 검증용으로 남기고 나머지로 학습하는 과정을 k번 반복해, 그 성능들을 평균내 일반화 성능을 추정하는 방법. 모든 데이터가 학습과 검증에 한 번씩 쓰이므로 단일 분할보다 안정적이며, 비지도학습에서는 밀도 추정의 우도나 대역폭 선택에 활용.</p>`,
