    id: 'adam',
    category: 'sup',
    subcategory: 'regression',
    title: 'Adam(Adaptive Moment estimation) : 아담 옵티마이저',
    subtitle: '기울기의 1차·2차 모멘트를 함께 추정해 파라미터마다 학습률을 자동 조절하는 최적화 기법',
    overview: `<p>모멘텀(기울기의 지수이동평균)과 RMSProp(기울기 제곱의 지수이동평균)을 결합한 기법. 각 파라미터마다 과거 기울기 크기에 따라 학습률을 다르게 적용하고, 초기 편향을 보정하는 항까지 포함해 안정적으로 수렴. 딥러닝에서 사실상 기본 옵티마이저로 자리잡음.</p>`,
    formula: `m_t = β₁m_{t−1} + (1−β₁)g_t,  v_t = β₂v_{t−1} + (1−β₂)g_t²,  θ ← θ − η·m̂_t/(√v̂_t + ε)`,
    features: `<p>파라미터별 적응적 학습률로 초기 학습률 설정에 덜 민감하고 희소한 기울기에도 잘 작동하며 대부분의 문제에서 빠르게 수렴하는 장점, 일반화 성능이 SGD+모멘텀보다 떨어질 수 있고 수렴이 이론적으로 보장되지 않는 경우가 있으며 메모리를 파라미터당 두 배 더 쓰는 단점.</p>`,
    applications: `<p>딥러닝 모델 학습의 기본 옵티마이저, 자연어·비전 모델의 대규모 사전학습, 희소 특징이 많은 추천 모델 학습에 널리 사용.</p>`,
    sklearnFunction: 'MLPRegressor(solver="adam")',
