    subcategory: 'regression',
    title: 'AdamW(Adam with decoupled Weight decay) : 아담W 옵티마이저',
    subtitle: 'Adam에서 가중치 감쇠를 손실이 아닌 갱신식에서 분리해 정규화 효과를 회복시킨 기법',
    overview: `<p>Adam에 L2 정규화를 손실 항으로 넣으면 적응적 학습률에 의해 정규화 강도가 파라미터마다 왜곡되는 문제를 해결한 기법. 가중치 감쇠를 기울기와 분리(decoupled)해 파라미터 갱신 단계에서 직접 적용하므로, 의도한 정규화 효과가 그대로 유지되어 일반화 성능이 개선됨. 트랜스포머 학습의 표준.</p>`,
    formula: 'θ ← θ − η·( m̂_t/(√v̂_t + ε) + λθ )  (λθ 항을 기울기와 분리해 직접 적용)',
    features: `<p>가중치 감쇠가 의도대로 작동해 Adam보다 일반화 성능이 뚜렷이 좋고 학습률과 감쇠 계수를 독립적으로 조정할 수 있는 장점, Adam과 마찬가지로 메모리 사용이 크고 감쇠 계수를 별도로 튜닝해야 하는 단점.</p>`,
    applications: `<p>BERT·GPT 등 트랜스포머 모델의 표준 옵티마이저, 비전 트랜스포머 학습, 대규모 사전학습 전반에 사용.</p>`,
