    title: 'Lookahead : 루카헤드',
    subtitle: '빠른 가중치가 여러 걸음 탐색한 뒤 느린 가중치가 그쪽으로 한 걸음 따라가는 이중 최적화 기법',
    overview: `<p>내부 옵티마이저(Adam·SGD 등)가 빠른 가중치로 k번 갱신하며 앞서 탐색하고, 느린 가중치가 그 결과 쪽으로 보간해 한 걸음 이동하는 이중 구조. 어떤 옵티마이저 위에도 감쌀 수 있으며, 앞선 탐색 결과를 평균내는 효과로 분산을 줄여 하이퍼파라미터에 대한 민감도를 낮춤.</p>`,
    formula: `φ_{t+1} = φ_t + α·(θ_{t,k} − φ_t)  (θ: 빠른 가중치 k회 갱신 결과, φ: 느린 가중치)`,
    features: `<p>기존 옵티마이저를 감싸 쓸 수 있어 도입이 쉽고 학습률 등 하이퍼파라미터 민감도를 크게 낮추며 분산 감소로 안정성이 높아지는 장점, 가중치 사본을 유지해 메모리가 늘고 k와 α라는 파라미터가 추가되며 항상 성능이 개선되지는 않는 단점.</p>`,
    applications: `<p>딥러닝 학습의 안정성 개선, 하이퍼파라미터 탐색 비용을 줄여야 하는 상황, 다른 옵티마이저와 조합한 성능 향상에 사용.</p>`,
