    overview: `<p>손실 함수를 현재 지점에서 2차 함수로 근사하고 그 근사의 최소점으로 바로 이동하는 방식. 곡률 정보를 쓰기 때문에 학습률을 따로 정할 필요가 없고 최적점 근처에서는 반복마다 정확도가 제곱으로 좋아지는 매우 빠른 수렴을 보이지만, 헤세 행렬 계산과 역행렬이 큰 부담.</p>`,
