    title: 'SGD(Stochastic Gradient Descent) : 확률적 경사하강법',
    subtitle: '한 번에 하나의 샘플로 기울기를 추정해 즉시 갱신하는 온라인 최적화 기법',
    overview: `<p>전체 데이터의 기울기를 계산하는 대신 무작위로 고른 샘플 하나의 기울기만으로 파라미터를 갱신하는 방식. 갱신이 매우 빈번하고 계산이 가벼워 대용량·스트리밍 데이터에 적합하며, 기울기에 섞인 잡음이 오히려 얕은 지역 최적해를 탈출하는 데 도움이 되기도 함.</p>`,
    formula: 'θ ← θ − η·∇_θ L(x_i, y_i)  (무작위로 선택한 샘플 i 하나)',
