    overview: `<p>학습 시작 시점에는 파라미터가 무작위 상태라 큰 학습률을 쓰면 기울기가 폭주해 학습이 망가지는 문제를, 초반 일정 구간 동안 학습률을 0에서 목표값까지 선형으로 끌어올려 해결하는 전략. 트랜스포머처럼 큰 배치와 Adam을 쓰는 학습에서 사실상 필수이며, 보통 워밍업 뒤에 감소 스케줄이 이어짐.</p>`,
