    category: 'sup',
    subcategory: 'regression',
    title: 'Binomial Regression : 이항 회귀',
    subtitle: '성공 횟수처럼 시행 횟수 대비 비율 형태인 반응변수를 모형화하는 GLM',
    overview: `<p>반응변수가 n번 시행 중 k번 성공한 형태일 때 사용하는 GLM으로, 이항분포와 로짓 연결함수를 결합. 개별 관측이 0/1인 로지스틱 회귀를 시행 횟수가 여럿인 경우로 일반화한 것이며, 같은 조건의 관측을 묶어 비율로 다룰 때 자연스럽게 적용.</p>`,
    formula: 'y ~ Binomial(n, p),  log(p/(1−p)) = Xβ  (로짓 연결함수)',
