    id: 'gamma-regression',
    category: 'sup',
    subcategory: 'regression',
    title: 'Gamma Regression : 감마 회귀',
    subtitle: '양수이면서 오른쪽으로 치우친 연속형 반응변수를 모형화하는 GLM',
    overview: `<p>보험 청구액이나 소요 시간처럼 값이 항상 양수이고 분포가 오른쪽으로 길게 치우친 데이터를 다루는 GLM. 분산이 평균의 제곱에 비례한다고 가정해 큰 값에서 변동이 커지는 성질을 자연스럽게 반영하며, 보통 로그 연결함수를 써서 계수를 배수 효과로 해석.</p>`,
    formula: 'y ~ Gamma(μ, ν),  Var(y) = μ²/ν,  log(μ) = Xβ  (로그 연결함수)',
    features: `<p>양수 치우친 분포를 자연스럽게 모형화하고 분산이 평균에 비례해 커지는 이분산성을 자동 반영하며 계수가 배수 효과로 해석되는 장점, 반응변수가 0을 포함하면 쓸 수 없고 분포 가정이 어긋나면 추정이 편향되는 단점.</p>`,
    applications: `<p>보험 청구액 모형(손해보험 요율 산정), 병원 재원기간·대기시간 분석, 강수량 등 양수 연속 데이터 분석에 사용.</p>`,
    sklearnFunction: 'GammaRegressor',
