    title: 'Inverse Gaussian Regression : 역가우시안 회귀',
    subtitle: '감마분포보다 더 심하게 오른쪽으로 치우친 양수 반응변수를 다루는 GLM',
    overview: `<p>양수이면서 치우침이 매우 심한 데이터를 위한 GLM으로, 분산이 평균의 세제곱에 비례한다고 가정. 브라운 운동이 특정 지점에 처음 도달하는 시간의 분포에서 유래해 첫 도달 시간(first passage time) 해석을 가지며, 감마 회귀로도 꼬리를 충분히 설명하지 못할 때 대안으로 사용.</p>`,
