    title: 'Negative Binomial Regression : 음이항 회귀',
    subtitle: '분산이 평균보다 큰 과산포 계수 데이터를 다루는 GLM',
    overview: `<p>포아송 회귀가 전제하는 "평균 = 분산"이 실제 계수 데이터에서 자주 깨지는 과산포 문제를 해결한 모형. 포아송의 평균 자체가 감마분포를 따라 변동한다고 보아 분산에 여유 모수를 추가하며, 분산이 평균의 이차식으로 커지도록 허용해 과산포를 흡수.</p>`,
    formula: 'Var(y) = μ + αμ²  (α: 과산포 모수, α → 0이면 포아송과 일치),  log(μ) = Xβ',
    features: `<p>과산포를 명시적으로 모형화해 포아송보다 표준오차 추정이 정확하고 계수의 유의성 판단이 신뢰할 만하며 여전히 로그 연결함수로 해석이 쉬운 장점, 모수가 하나 늘어 추정이 복잡하고 과소산포 데이터에는 적용할 수 없는 단점.</p>`,
    applications: '<p>보험 청구 건수, 교통사고 발생 건수, 유전자 발현 카운트(RNA-seq) 분석에 널리 사용.</p>',
    sklearnFunction: 'NegativeBinomial (statsmodels)',
    sklearnGuideURL: 'https://www.statsmodels.org/stable/glm.html',
