    title: 'Poisson Regression : 포아송 회귀',
    subtitle: '단위 시간·공간당 사건 발생 횟수 같은 계수 데이터를 모형화하는 대표적 GLM',
    overview: `<p>반응변수가 0 이상의 정수인 계수(count) 데이터를 다루는 GLM으로, 포아송분포와 로그 연결함수를 결합. 로그 연결 덕분에 예측값이 항상 양수이고 계수는 "설명변수 1단위 증가 시 발생률이 몇 배가 되는가"로 해석됨. 관측 기간이 다르면 오프셋으로 보정.</p>`,
    formula: 'y ~ Poisson(μ),  log(μ) = Xβ  (+ offset),  E[y] = Var(y) = μ',
    features: `<p>계수 데이터를 자연스럽게 다루고 계수가 발생률 배수로 직관적으로 해석되며 관측 노출량을 오프셋으로 보정할 수 있는 장점, 평균과 분산이 같다는 가정이 실제로는 자주 깨져(과산포) 표준오차가 과소추정되고 0이 많은 데이터에는 부적합한 단점.</p>`,
