    overview: `<p>다항 회귀에서 차수가 높아지면 특징 수가 폭증하는 문제를, 커널 트릭으로 우회한 기법. 다항 커널 k(x,z)=(γxᵀz+r)^d 를 쓰면 d차 다항 특징들의 내적을 직접 계산하지 않고도 얻을 수 있어, 고차 다항 관계를 계산 부담 없이 학습. 커널 릿지 회귀나 SVR과 결합해 사용.</p>`,
