    overview: `<p>설명변수가 여러 개일 때 각 변수의 거듭제곱뿐 아니라 변수 간 곱(교차항)까지 특징으로 추가해 회귀하는 기법. x₁², x₂², x₁x₂ 같은 항이 들어가 변수 간 상호작용과 곡면 형태의 관계를 표현할 수 있으며, 파라미터에 대해서는 여전히 선형이라 최소제곱으로 풀림.</p>`,
