    overview: `<p>일반 다항 회귀에서 x, x², x³이 서로 강하게 상관되어 계수가 불안정해지는 문제를, 서로 직교하도록 변환한 다항 기저(르장드르·체비쇼프 등)로 해결한 기법. 각 차수의 계수가 독립적으로 해석되고 차수를 추가해도 기존 계수가 변하지 않아 차수 선택이 훨씬 안정적.</p>`,
