    category: 'sup',
    subcategory: 'regression',
    title: 'Sparse Group Lasso Regression : 희소 그룹 라쏘 회귀',
    subtitle: '그룹 단위 선택과 그룹 내부 개별 변수 선택을 동시에 수행하는 정규화 회귀',
    overview: `<p>그룹 라쏘가 그룹 전체를 통째로 선택하거나 버릴 뿐 그룹 안에서 개별 변수를 고르지 못하는 한계를, L1 페널티를 함께 부과해 해결한 기법. 그룹 수준의 희소성과 그룹 내부의 희소성을 동시에 얻어, "관련 있는 그룹을 고르고 그 안에서도 핵심 변수만 남기는" 두 단계 선택을 한 번에 수행.</p>`,
