    subtitle: '비선형 회귀 모형의 파라미터에 사전분포를 두고 사후분포로 추론하는 기법',
    overview: `<p>비선형 회귀의 파라미터를 점 추정하는 대신 확률분포로 다루어, 예측값과 함께 불확실성까지 제공하는 접근. 비선형이라 사후분포가 해석적으로 구해지지 않으므로 MCMC나 변분추론으로 근사하며, 표본이 적거나 파라미터에 물리적 제약이 있을 때 사전분포로 지식을 주입할 수 있어 유리.</p>`,
    formula: `y = f(x; θ) + ε,  p(θ|D) ∝ p(D|θ)·p(θ)  → MCMC/변분추론으로 사후분포 근사`,
    features: `<p>예측 불확실성을 정량화하고 사전지식으로 파라미터를 제약할 수 있으며 표본이 적어도 안정적인 장점, MCMC 계산이 매우 무겁고 수렴 진단이 필요하며 사전분포 선택이 결과에 영향을 주는 단점.</p>`,
    applications: `<p>약동학 모형의 파라미터 추정, 물리·화학 실험의 비선형 모형 적합, 불확실성 정량화가 중요한 공학 예측에 사용.</p>`,
