    category: 'sup',
    subcategory: 'regression',
    title: 'Deep Gaussian Process Regression : 딥 가우시안 프로세스 회귀',
    subtitle: '가우시안 프로세스를 여러 층으로 쌓아 표현력을 높인 비모수 베이지안 회귀',
    overview: `<p>단일 가우시안 프로세스가 커널 하나로 표현할 수 있는 함수 형태에 한계가 있다는 문제를, GP를 여러 층으로 합성해 해결한 모델. 각 층의 출력이 다음 층의 입력이 되어 훨씬 복잡한 비선형 함수를 표현하면서도, 베이지안 모델이라 예측 불확실성을 층층이 전파해 제공.</p>`,
