    subtitle: '곡선이나 시계열 전체를 하나의 함수 관측치로 보고 회귀 관계를 모형화하는 기법',
    overview: `<p>각 관측이 하나의 숫자가 아니라 시간·파장에 따라 관측된 곡선 전체인 데이터를 다루는 회귀. 설명변수가 함수이면 계수도 함수가 되어 "언제·어느 구간이 결과에 영향을 주는가"를 곡선으로 보여주며, 기저함수 전개나 함수형 주성분으로 무한차원 문제를 유한차원으로 축소해 추정.</p>`,
