    subcategory: 'regression',
    title: `GAMLSS(Generalized Additive Models for Location, Scale and Shape) : 위치-규모-형상 회귀`,
    subtitle: '평균뿐 아니라 분산·왜도·첨도까지 설명변수로 모형화하는 확장 회귀',
    overview: `<p>GLM·GAM이 분포의 평균만 설명변수와 연결하는 것과 달리, 분포의 위치(평균)·규모(분산)·형상(왜도·첨도) 모든 모수를 각각 설명변수의 함수로 모형화하는 확장. 이분산성이나 왜도가 설명변수에 따라 변하는 데이터를 정확히 다룰 수 있고, 정규분포에 국한되지 않는 다양한 분포족을 지원.</p>`,
    formula: `g₁(μ) = X₁β₁,  g₂(σ) = X₂β₂,  g₃(ν) = X₃β₃,  g₄(τ) = X₄β₄  (위치·규모·형상 각각 모형화)`,
    features: `<p>분산과 분포 형태까지 설명변수로 모형화해 이분산·왜도 데이터를 정확히 다루고 100여 가지 분포족을 지원하며 성장 곡선의 백분위수 산출에 표준으로 쓰이는 장점, 모수가 많아 추정이 불안정할 수 있고 분포족 선택과 평활 설정이 복잡하며 계산이 무거운 단점.</p>`,
    applications: `<p>WHO 소아 성장 곡선의 백분위수 산출, 보험 손해액의 분산 구조 모형화, 이분산성이 뚜렷한 경제 데이터 분석에 사용.</p>`,
    sklearnFunction: 'gamlss (R)',
    sklearnGuideURL: 'https://www.gamlss.com/',
    sklearnAPIURL: '',
    sklearnExampleURL: '',
    huggingfaceURL: '',
    spaceURL: '',
    papersWithCodeURL: `https://rss.onlinelibrary.wiley.com/doi/10.1111/j.1467-9876.2005.00510.x`
