    title: `Multinomial Logistic Regression / Softmax Regression : 다항 로지스틱 회귀 / 소프트맥스 회귀`,
    subtitle: '소프트맥스로 여러 클래스의 확률을 동시에 예측하는 로지스틱 회귀의 다중 클래스 확장',
    overview: `<p>이진 로지스틱 회귀를 클래스가 셋 이상인 경우로 확장한 모델. 각 클래스마다 점수를 계산한 뒤 소프트맥스로 정규화해 합이 1인 확률 분포를 출력하며, 클래스별로 이진 분류기를 따로 만드는 방식과 달리 모든 클래스를 하나의 모형에서 동시에 학습. 신경망 출력층의 표준 구성이기도 함.</p>`,
    formula: `P(y=k|x) = exp(w_kᵀx) / Σ_{j=1}^{K} exp(w_jᵀx),  Loss = −Σ_i log P(y_i|x_i)`,
    features: `<p>모든 클래스를 하나의 모형에서 동시에 학습해 확률 합이 1로 일관되고 계수 해석이 가능하며 신경망 출력층으로 바로 확장되는 장점, 클래스 수가 많으면 파라미터가 비례해 늘고 결정 경계가 선형이며 클래스 불균형에 취약한 단점.</p>`,
    applications: `<p>다중 클래스 문서 분류, 이미지 분류 모델의 출력층, 고객 세그먼트 분류, 딥러닝 분류 모델 전반에 표준으로 사용.</p>`,
