    title: 'Probit Regression : 프로빗 회귀',
    subtitle: '표준정규 누적분포함수를 연결함수로 사용해 이진 반응을 모형화하는 GLM',
    overview: `<p>로지스틱 회귀와 목적은 같지만 시그모이드 대신 표준정규분포의 누적분포함수를 연결함수로 쓰는 모형. 관측되지 않는 잠재 효용이 정규분포를 따르고 그것이 임계값을 넘으면 1이 관측된다는 잠재변수 해석이 자연스러워, 경제학의 이산선택 모형에서 널리 사용.</p>`,
