    title: 'Bayesian Network Classification : 베이즈 네트워크 분류',
    subtitle: '변수 간 조건부 의존 구조를 방향 그래프로 표현해 분류하는 확률 그래프 모형',
    overview: `<p>변수들 사이의 조건부 독립 관계를 방향 비순환 그래프로 표현하고, 각 노드의 조건부 확률표를 학습해 분류하는 모형. 나이브 베이즈가 모든 특징이 독립이라고 가정하는 것과 달리 특징 간 실제 의존 관계를 그래프로 명시하므로 더 정확하며, 그래프 자체가 도메인 지식을 담는 해석 가능한 구조가 됨.</p>`,
    formula: `P(X₁,...,X_n) = ∏_{i=1}^{n} P(X_i | Parents(X_i))  → argmax_c P(c|x)`,
