    subtitle: '모든 특징이 조건부 독립이라는 단순한 가정으로 베이즈 정리를 적용하는 고속 분류기',
    overview: `<p>베이즈 정리로 사후확률을 계산하되, 클래스가 주어지면 모든 특징이 서로 독립이라는 강한(순진한) 가정을 도입해 계산을 단순화한 분류기. 이 가정 덕분에 결합확률이 개별 확률의 곱으로 분해되어 학습이 한 번의 데이터 스캔으로 끝나며, 가정이 현실과 달라도 분류 성능은 의외로 좋은 경우가 많음.</p>`,
    formula: 'ŷ = argmax_c P(c)·∏_{i=1}^{n} P(x_i | c)',
