    subtitle: '이미지의 공간 구조와 시퀀스의 시간 구조를 각각 특화해 처리하는 두 신경망 계열',
    overview: `<p>CNN은 작은 필터를 이미지 전역에 반복 적용해 위치가 바뀌어도 같은 패턴을 인식하는 구조로, 가중치 공유와 국소 연결로 파라미터를 크게 줄임. RNN은 은닉 상태를 다음 시점으로 전달해 시퀀스의 문맥을 기억하는 구조로, 기울기 소실을 게이트로 보완한 LSTM·GRU가 실무 표준. 각각 공간·시간 구조에 특화된 귀납적 편향을 가짐.</p>`,
    formula: `CNN: (f*x)(i,j) = ΣΣ f(m,n)·x(i−m, j−n),  RNN: h_t = σ(W_hh_{t−1} + W_xx_t + b)`,
    features: `<p>CNN은 가중치 공유로 파라미터가 적고 위치 불변성을 갖추며, RNN은 가변 길이 시퀀스를 자연스럽게 처리하는 장점, CNN은 전역적 관계 포착이 약하고 RNN은 순차 처리라 병렬화가 어렵고 장기 의존성에 취약해 두 계열 모두 트랜스포머로 대체되는 추세인 단점.</p>`,
    applications: `<p>CNN은 이미지 분류·객체 검출·의료 영상 진단에, RNN은 시계열 예측·음성 인식·기계 번역에 사용.</p>`,
    sklearnFunction: 'Conv2d / LSTM (PyTorch)',
