    subtitle: '완전연결 은닉층을 쌓아 비선형 함수를 근사하는 가장 기본적인 신경망',
    overview: `<p>입력층과 출력층 사이에 하나 이상의 완전연결 은닉층을 두고 각 층마다 비선형 활성함수를 적용하는 기본 신경망 구조. 보편 근사 정리에 따라 은닉 유닛이 충분하면 임의의 연속 함수를 근사할 수 있으며, 역전파로 학습. 회귀와 분류 모두에 쓰이고 딥러닝의 출발점이 되는 구조.</p>`,
