    title: 'Transformer : 트랜스포머',
    subtitle: '자기 어텐션만으로 시퀀스 전체의 관계를 병렬 처리하는 신경망 구조',
    overview: `<p>순환 구조 없이 자기 어텐션만으로 시퀀스를 처리하는 구조. 각 위치가 다른 모든 위치를 직접 참조해 장거리 의존성을 한 번에 포착하고, 순차 처리가 없어 완전 병렬 학습이 가능. 위치 정보는 위치 인코딩으로 주입하며, 현대 대형 언어모델과 비전 모델의 공통 기반 구조가 됨.</p>`,
    formula: `Attention(Q,K,V) = softmax(QKᵀ/√d_k)·V,  MultiHead = Concat(head_1,...,head_h)W^O`,
    features: `<p>장거리 의존성을 직접 포착하고 완전 병렬 학습이 가능해 대규모 사전학습에 적합하며 텍스트·이미지·오디오에 두루 적용되는 장점, 어텐션 계산이 시퀀스 길이의 제곱에 비례해 긴 입력에 부담이 크고 대량의 데이터와 계산 자원이 필요하며 소규모 데이터에서는 과적합되는 단점.</p>`,
    applications: `<p>대형 언어모델(GPT·BERT)의 기반 구조, 기계 번역과 문서 요약, 비전 트랜스포머(ViT)를 통한 이미지 분류, 시계열 예측에 광범위하게 사용.</p>`,
