    overview: `<p>MAPE가 0 근처에서 발산하는 문제를 해결한 지표로, 모델의 절대 오차를 "바로 전 시점 값을 그대로 예측"하는 나이브 예측의 절대 오차로 나눔. 1보다 작으면 나이브 예측보다 낫다는 뜻이라 해석 기준이 명확하고, 시계열 예측 대회(M4 등)의 표준 평가 지표.</p>`,
