    overview: `<p>예측 오차의 절댓값이 아니라 부호를 그대로 유지한 채 평균낸 값. 양수 오차와 음수 오차가 상쇄되므로 오차의 절대적 크기는 알 수 없지만, 모델이 체계적으로 과대·과소 예측하는 편향(bias)이 있는지를 곧바로 드러냄. 0에 가까우면 편향이 없다는 뜻.</p>`,
