    overview: `<p>실제값과 예측값에 각각 log(1+y)를 취한 뒤 MSE를 계산하는 지표. 로그 변환 덕분에 값이 큰 관측(예: 매출 100만 vs 101만)과 값이 작은 관측(예: 매출 100 vs 101)의 절대 오차가 아니라 상대적 비율 오차를 비슷한 비중으로 다루며, 과소예측보다 과대예측에 더 큰 벌점을 줌.</p>`,
