    overview: `<p>MSE에 제곱근을 취해 단위를 원래 데이터와 같게 되돌린 지표. MSE의 "큰 오차에 더 큰 벌점"이라는 성질은 유지하면서 값 자체는 직접 해석할 수 있어, 회귀 모델 성능 보고에서 MAE와 함께 가장 널리 쓰이는 지표.</p>`,
