    overview: `<p>MSLE에 제곱근을 취한 지표로, 로그 변환된 비율 오차를 다시 해석 가능한 스케일로 되돌린 값. 값의 규모가 크게 다른 타깃(가격·트래픽 등)에서 상대적 오차를 공정하게 평가하면서도, RMSE처럼 어느 정도 직접 해석이 가능한 형태를 제공.</p>`,
