    subtitle: '실제 음성 중 모델이 정확히 음성으로 판정한 비율로, 재현율의 음성 버전인 지표',
    overview: `<p>실제로 음성인 것들 중 모델이 올바르게 음성으로 판정한 비율. 재현율(민감도)이 양성을 놓치지 않는 능력을 보는 것과 짝을 이루어, 음성을 잘못 양성으로 판정하지 않는 능력을 나타내며, 의료 진단에서 민감도와 항상 함께 보고됨.</p>`,
