    subtitle: '학습 데이터 양 또는 하이퍼파라미터에 따른 성능 변화를 그려 과적합·과소적합을 진단하는 그래프',
    overview: `<p>학습 곡선은 훈련 데이터 크기를 늘려가며 훈련·검증 성능이 어떻게 변하는지, 검증 곡선은 하이퍼파라미터(트리 깊이 등)를 바꿔가며 성능이 어떻게 변하는지를 그린 그래프. 두 곡선의 간격과 방향으로 데이터 부족(더 모으면 개선), 과적합(간격이 큼), 과소적합(둘 다 낮음)을 진단.</p>`,
